package org.dashfoundation.dashsdk.persistence.entities

import androidx.room.Entity
import androidx.room.ForeignKey
import androidx.room.Index
import androidx.room.PrimaryKey
import java.util.Date

/**
 * Port of `PersistentAccount.swift` — one HD wallet account (BIP44,
 * CoinJoin, Identity, PlatformPayment, …).
 *
 * Primary key: SwiftData identifies accounts by the hidden
 * `persistentModelID` (rowid); the `#Unique` tuple is a uniqueness
 * constraint, not the relational key children point at. We mirror that
 * storage model with a surrogate autogenerated [id] (rowid) — children
 * (`core_addresses`, `platform_addresses`, `txos`) FK onto it — and carry
 * the Swift `#Unique<PersistentAccount>([\.wallet, \.accountType,
 * \.accountIndex, \.standardTag, \.registrationIndex, \.keyClass,
 * \.userIdentityId, \.friendIdentityId])` as a unique index (an 8-column
 * composite PK including two BLOBs is not referenceable by child FKs).
 *
 * Swift `@Attribute(.unique)` on `accountExtendedPubKeyBytes` → unique
 * index; SQLite allows multiple NULLs, matching Swift's rationale.
 *
 * The parent [walletId] FK CASCADEs (Swift `PersistentWallet.accounts`
 * declares `.cascade`).
 */
@Entity(
    tableName = "accounts",
    indices = [
        Index(value = ["walletId"]),
        Index(
            value = [
                "walletId", "accountType", "accountIndex", "standardTag",
                "registrationIndex", "keyClass", "userIdentityId", "friendIdentityId",
            ],
            unique = true,
        ),
        Index(value = ["accountExtendedPubKeyBytes"], unique = true),
    ],
    foreignKeys = [
        ForeignKey(
            entity = WalletEntity::class,
            parentColumns = ["walletId"],
            childColumns = ["walletId"],
            onDelete = ForeignKey.CASCADE,
        ),
    ],
)
data class AccountEntity(
    /** Surrogate rowid — mirror of SwiftData's hidden `persistentModelID`. */
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    /** Parent wallet id. Swift `wallet: PersistentWallet` (non-optional). */
    val walletId: ByteArray,
    /**
     * `AccountTypeTagFFI` discriminant (0 = Standard … 16 =
     * IdentityAuthenticationBls). Swift `UInt32` → [Int].
     */
    val accountType: Int,
    /** Account index within the type. Swift `UInt32` → [Int]. */
    val accountIndex: Int,
    val accountTypeName: String,
    /** Duffs; Swift `UInt64` → [Long] (unsigned semantics). */
    val balanceConfirmed: Long = 0,
    /** Duffs; Swift `UInt64` → [Long] (unsigned semantics). */
    val balanceUnconfirmed: Long = 0,
    /** Highest used external index, -1 = none. Swift `Int32`. */
    val externalHighestUsed: Int = -1,
    /** Highest used internal (change) index, -1 = none. Swift `Int32`. */
    val internalHighestUsed: Int = -1,
    /** `StandardAccountTypeTagFFI` (0 BIP44, 1 BIP32). Swift `UInt8` → [Int]. */
    val standardTag: Int = 0,
    /** `IdentityTopUp.registration_index`. Swift `UInt32` → [Int]. */
    val registrationIndex: Int = 0,
    /** `PlatformPayment.key_class`. Swift `UInt32` → [Int]. */
    val keyClass: Int = 0,
    /** `Dashpay*.user_identity_id` (32 bytes); empty for other variants. */
    val userIdentityId: ByteArray = ByteArray(0),
    /** `Dashpay*.friend_identity_id` (32 bytes); empty for other variants. */
    val friendIdentityId: ByteArray = ByteArray(0),
    /**
     * Bincode-encoded `ExtendedPubKey` — opaque passthrough consumed by the
     * Rust load path (`Account::from_xpub`). `null` = not yet persisted.
     */
    val accountExtendedPubKeyBytes: ByteArray? = null,
    val createdAt: Date = Date(),
    val lastUpdated: Date = Date(),
) {
    override fun equals(other: Any?): Boolean = other is AccountEntity && id == other.id

    override fun hashCode(): Int = id.hashCode()
}
